{
  "key": "gh-361",
  "fields": {
    "summary": "file_write must create parent directories (PathNotFoundException vs Java)",
    "description": "Live: the token-usage reporter job (dmtools-agents ai_teammate_token_usage_reporter.json) failed at the final write under the Dart CLI:

Error: Bad state: JavaScript execution failed: Error: Tool execution failed: PathNotFoundException: Cannot open file, path = '.../outputs/token_usage/ai_teammate_token_usage_cache.json' (OS Error: No such file or directory, errno = 2)

Java's FileTools.write creates parent directories (verify in FileTools.java); the Dart file_write tool must match — create parents before writing. Regression test: file_write to a nested non-existent path succeeds.

## Machine jobs
- [x] ▶ dev (fa-story-dev) · [run](https://github.com/epam/dmtools-dart/actions/runs/37364293660) · started 19:41 · done 19:59 ✅"
  }
}

diff --git a/lib/src/js/tool_bridge.dart b/lib/src/js/tool_bridge.dart
index 2dbaa243..1015a217 100644
--- a/lib/src/js/tool_bridge.dart
+++ b/lib/src/js/tool_bridge.dart
@@ -475,9 +475,18 @@ class ToolBridge {
     }
   }

+  /// Java `FileTools.writeFile` parity (gh-361): creates missing parent
+  /// directories before writing, so a write to a nested non-existent path
+  /// (e.g. the token-usage reporter's `outputs/token_usage/` cache)
+  /// succeeds instead of failing with `PathNotFoundException`.
   String _writeFile(String path, String content) {
     try {
-      File(_resolve(path)).writeAsStringSync(content);
+      final resolved = _resolve(path);
+      final parent = File(resolved).parent;
+      if (!parent.existsSync()) {
+        parent.createSync(recursive: true);
+      }
+      File(resolved).writeAsStringSync(content);
       return _successJson;
     } catch (e) {
       return _err(e.toString());
diff --git a/test/js/file_tools_bridge_test.dart b/test/js/file_tools_bridge_test.dart
index 987a9be9..eeceaa3e 100644
--- a/test/js/file_tools_bridge_test.dart
+++ b/test/js/file_tools_bridge_test.dart
@@ -1,4 +1,5 @@
-/// JS-bridge `file_list`/`file_exists` parity with Java `FileTools`
+/// JS-bridge `file_list`/`file_exists`/`file_write` parity with Java
+/// `FileTools`
 /// (epam/dm.ai 3fa210e6, #635): the tools the agents suite relies on,
 /// exposed through the same `executeToolViaJava` path the JS side uses.
 ///
@@ -24,6 +25,7 @@ void main() {
   tearDown(() => dir.deleteSync(recursive: true));
   fileListTests();
   fileExistsTests();
+  fileWriteTests();
 }

 void fileListTests() {
@@ -99,3 +101,61 @@ void fileExistsTests() {
     });
   });
 }
+
+void fileWriteTests() {
+  group('JS-bridge file_write (Java FileTools.writeFile parity)', () {
+    final bridge = ToolBridge(registry: createDefaultToolRegistry());
+
+    test('creates missing parent directories before writing (gh-361)', () {
+      // Java writeFile: Files.createDirectories(parentDir) before
+      // Files.writeString — a write to a nested non-existent path succeeds
+      // (the token-usage reporter depends on this for its cache file).
+      final nested = '${dir.path}/outputs/token_usage/cache.json';
+
+      final result = jsonDecode(
+        bridge.execute('file_write', {
+          'path': nested,
+          'content': '{"tokens": 42}',
+        }),
+      ) as Map<String, dynamic>;
+
+      expect(result.containsKey('error'), isFalse, reason: '$result');
+      expect(File(nested).readAsStringSync(), '{"tokens": 42}');
+    });
+
+    test('creates multi-level parents in one call', () {
+      final nested = '${dir.path}/a/b/c/d/e.txt';
+
+      expect(
+        jsonDecode(bridge.execute('file_write', {
+          'path': nested,
+          'content': 'deep',
+        })),
+        {'success': true},
+      );
+      expect(File(nested).readAsStringSync(), 'deep');
+    });
+
+    test('overwrites an existing file without touching the parent', () {
+      Directory('${dir.path}/sub').createSync();
+      final existing = '${dir.path}/sub/a.txt';
+      File(existing).writeAsStringSync('old');
+
+      expect(
+        jsonDecode(bridge.execute('file_write', {
+          'path': existing,
+          'content': 'new',
+        })),
+        {'success': true},
+      );
+      expect(File(existing).readAsStringSync(), 'new');
+    });
+
+    test('rejects an empty path with the error envelope', () {
+      final result = jsonDecode(
+        bridge.execute('file_write', {'path': '', 'content': 'x'}),
+      ) as Map<String, dynamic>;
+      expect(result['error'], isA<String>());
+    });
+  });
+}

